"""Write frontend/.env.local for LOCAL DEVELOPMENT from backend/.env (shares the revalidation secret)."""

from __future__ import annotations

from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]


def main() -> None:
    env = {}
    for line in (ROOT / "backend" / ".env").read_text(encoding="utf-8").splitlines():
        if "=" in line and not line.startswith("#"):
            k, _, v = line.partition("=")
            env[k.strip()] = v.strip()
    target = ROOT / "frontend" / ".env.local"
    target.write_text(
        "# Generated by backend/scripts/sync_frontend_env.py — LOCAL DEVELOPMENT ONLY. Do not commit.\n"
        "INTERNAL_API_URL=http://127.0.0.1:8000\n"
        f"NEXT_PUBLIC_SITE_URL={env.get('PUBLIC_BASE_URL', 'http://localhost:8088')}\n"
        f"REVALIDATE_SECRET={env['FRONTEND_REVALIDATE_SECRET']}\n"
        f"NEXT_PUBLIC_DEV_TOOLS={'true' if env.get('DJANGO_ENV', 'development') == 'development' else 'false'}\n",
        encoding="utf-8",
    )
    print(f"Wrote {target}")


if __name__ == "__main__":
    main()
